pr.solution:
def match(v, crit):
    for op in ('>=','<=','<>','>','<','='):
        if crit.startswith(op):
            val = crit[len(op):]
            break
    else:
        op, val = '=', crit
    try:
        a, b = float(v), float(val)
    except (TypeError, ValueError):
        a, b = str(v).lower(), str(val).lower()
    return {'>=':a>=b,'<=':a<=b,'<>':a!=b,'>':a>b,'<':a<b,'=':a==b}[op]

def countif(rng, crit):
    return sum(1 for v in rng if match(v, crit))

def sumif(rng, crit, sum_rng):
    return sum(s for v, s in zip(rng, sum_rng) if match(v, crit))

