pr.solution:
def vlookup(x, table, col):
    res = '#N/A'
    for row in table:
        if row[0] <= x:
            res = row[col-1]
        else:
            break
    return res

def rank(x, ref, order=0):
    if order == 0:
        return 1 + sum(1 for v in ref if v > x)
    return 1 + sum(1 for v in ref if v < x)

